'use client';
import { useEffect, useState } from 'react';
import { getRegionalBrand, parseRegion, type RegionId } from '@/lib/regional-branding';
export default function useRegionalBranding(initialRegion: RegionId = 'nationwide') {
  const [region, updateRegion] = useState<RegionId>(initialRegion);
  useEffect(() => {
    const sync = () => updateRegion(parseRegion(new URLSearchParams(window.location.search).get('region')));
    sync(); window.addEventListener('popstate', sync);
    return () => window.removeEventListener('popstate', sync);
  }, []);
  function setRegion(value: string) {
    const next = parseRegion(value);
    if (next === region) return;
    const url = new URL(window.location.href);
    if (next === 'nationwide') url.searchParams.delete('region');
    else url.searchParams.set('region', next);
    window.history.pushState({ ...window.history.state }, '', url);
    updateRegion(next);
  }
  return { region, brand: getRegionalBrand(region), setRegion };
}
